import{_ as n,o as t,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const c=JSON.parse('{"title":"Grids verknüpfen","description":"Einträge zwischen Grids verknüpfen und Daten sinnvoll auf mehrere Tabellen verteilen.","frontmatter":{"title":"Grids verknüpfen","description":"Einträge zwischen Grids verknüpfen und Daten sinnvoll auf mehrere Tabellen verteilen."},"headers":[],"relativePath":"grids/verknuepfungen.md","filePath":"grids/verknuepfungen.md","lastUpdated":1786174778000}'),a={name:"grids/verknuepfungen.md"};function s(l,e,d,u,h,o){return t(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="grids-verknupfen" tabindex="-1">Grids verknüpfen <a class="header-anchor" href="#grids-verknupfen" aria-label="Permalink to &quot;Grids verknüpfen&quot;">​</a></h1><p>Eine <strong>Verknüpfung</strong> verbindet einen Eintrag mit einem oder mehreren Einträgen eines anderen Grids. Damit verteilen Sie Daten sinnvoll, statt alles in eine breite Tabelle zu pressen.</p><h2 id="wann-sich-das-lohnt" tabindex="-1">Wann sich das lohnt <a class="header-anchor" href="#wann-sich-das-lohnt" aria-label="Permalink to &quot;Wann sich das lohnt&quot;">​</a></h2><p>Wenn sich Werte wiederholen, gehören sie in ein eigenes Grid.</p><p>Ein Beispiel: Sie erfassen Anmeldungen zu Veranstaltungen. Ohne Verknüpfung steht in jeder Anmeldung erneut der Veranstaltungsname, das Datum und der Ort. Ändert sich der Ort, müssen Sie ihn überall nachziehen.</p><p>Mit Verknüpfung:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Grid „Veranstaltungen&quot;        Grid „Anmeldungen&quot;</span></span>
<span class="line"><span>├── Titel                     ├── Name</span></span>
<span class="line"><span>├── Datum          ←──────────┤ Veranstaltung   (Eintrag verknüpfen)</span></span>
<span class="line"><span>├── Ort                       ├── E-Mail</span></span>
<span class="line"><span>└── Preis                     └── Status</span></span></code></pre></div><p>Der Ort steht <strong>einmal</strong>. Jede Anmeldung verweist darauf.</p><div class="tip custom-block"><p class="custom-block-title">Die Faustregel</p><p>Steht ein Wert in mehreren Zeilen identisch da, gehört er in ein eigenes Grid. Das gilt für Kunden, Produkte, Standorte, Projekte, Kategorien.</p></div><h2 id="die-beiden-verknupfungstypen" tabindex="-1">Die beiden Verknüpfungstypen <a class="header-anchor" href="#die-beiden-verknupfungstypen" aria-label="Permalink to &quot;Die beiden Verknüpfungstypen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Spaltentyp</th><th>Verweist auf</th></tr></thead><tbody><tr><td><strong>Eintrag verknüpfen</strong></td><td>genau einen Eintrag</td></tr><tr><td><strong>Mehrere Einträge verknüpfen</strong></td><td>beliebig viele Einträge</td></tr></tbody></table><p><strong>Eintrag verknüpfen</strong> ist der Normalfall: eine Anmeldung gehört zu einer Veranstaltung, eine Rechnung zu einem Kunden.</p><p><strong>Mehrere Einträge verknüpfen</strong> nutzen Sie, wenn mehrere Dinge zusammengehören: ein Projekt hat mehrere Beteiligte, eine Rechnung mehrere Positionen.</p><h2 id="verknupfung-anlegen" tabindex="-1">Verknüpfung anlegen <a class="header-anchor" href="#verknupfung-anlegen" aria-label="Permalink to &quot;Verknüpfung anlegen&quot;">​</a></h2><ol><li>Legen Sie im Grid ein neues Feld an.</li><li>Wählen Sie <strong>Eintrag verknüpfen</strong> oder <strong>Mehrere Einträge verknüpfen</strong>.</li><li>Wählen Sie unter <em>Legen Sie die Grid Ansicht fest</em> die Zielansicht.</li></ol><div class="warning custom-block"><p class="custom-block-title">Sie wählen eine Ansicht, nicht ein Grid</p><p>Die Auswahl erfolgt über eine <strong>Ansicht</strong> des Zielgrids. Das hat eine praktische Folge: Ist die Ansicht gefiltert, stehen nur die gefilterten Einträge zur Auswahl.</p><p>Das lässt sich nutzen — eine Ansicht „Aktive Kunden&quot; verhindert, dass jemand einen inaktiven Kunden auswählt. Es kann aber auch überraschen, wenn ein erwarteter Eintrag nicht auftaucht. In dem Fall prüfen Sie den Filter der Zielansicht.</p></div><h2 id="verknupfung-nutzen" tabindex="-1">Verknüpfung nutzen <a class="header-anchor" href="#verknupfung-nutzen" aria-label="Permalink to &quot;Verknüpfung nutzen&quot;">​</a></h2><p>In der Tabelle öffnet ein Klick auf das Feld die Auswahl. Sie suchen den gewünschten Eintrag und wählen ihn aus. Findet sich nichts, meldet ApptiveGrid <em>Kein passender Eintrag gefunden.</em></p><p>In <a href="/docs/formulare/felder-konfigurieren">Formularen</a> erscheint dieselbe Auswahl für Ausfüllende.</p><h2 id="die-grenze-keine-verschachtelten-verknupfungen" tabindex="-1">Die Grenze: keine verschachtelten Verknüpfungen <a class="header-anchor" href="#die-grenze-keine-verschachtelten-verknupfungen" aria-label="Permalink to &quot;Die Grenze: keine verschachtelten Verknüpfungen&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Verknüpfungen lassen sich nicht beliebig staffeln</p><p>Versuchen Sie, auf ein Grid zu verweisen, das seinerseits schon anderswo verknüpft ist, meldet ApptiveGrid:</p><blockquote><p><em>Links auf Grids die bereits an einer anderen Stelle verlinkt wurden, sind noch nicht möglich.</em></p></blockquote><p>Eine Kette wie <code>Anmeldung → Veranstaltung → Veranstaltungsort</code> ist damit nicht möglich.</p></div><p><strong>Was Sie stattdessen tun können:</strong></p><ul><li><strong>Datenmodell flach halten.</strong> Legen Sie Ort und Datum direkt in „Veranstaltungen&quot; ab, statt einen weiteren Verweis zu bauen.</li><li><strong>Direkt verknüpfen.</strong> Verweisen Sie aus „Anmeldungen&quot; zusätzlich unmittelbar auf „Veranstaltungsorte&quot;.</li><li><strong>Wert übernehmen.</strong> Holen Sie den benötigten Wert über ein <a href="/docs/grids/berechnete-felder">berechnetes Feld</a> herüber, statt eine weitere Verknüpfung anzulegen.</li></ul><p>Planen Sie Ihr Datenmodell von Anfang an mit dieser Grenze. Nachträglich umzubauen ist aufwendig.</p><h2 id="eintrage-mit-verknupfungen-loschen" tabindex="-1">Einträge mit Verknüpfungen löschen <a class="header-anchor" href="#eintrage-mit-verknupfungen-loschen" aria-label="Permalink to &quot;Einträge mit Verknüpfungen löschen&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Verknüpfte Einträge lassen sich nicht ohne Weiteres löschen</p><p>Wird ein Eintrag anderswo referenziert, meldet ApptiveGrid:</p><blockquote><p><em>Löschen nicht möglich. Der Eintrag ist noch an einer anderen Stelle referenziert.</em></p></blockquote><p>Oder, wenn der verweisende Eintrag benannt werden kann:</p><blockquote><p><em>Löschen nicht möglich. Der Eintrag wird noch von {Eintrag} referenziert.</em></p></blockquote><p>Lösen Sie zuerst die Verknüpfungen, die auf diesen Eintrag zeigen. Das ist eine Schutzfunktion — sie verhindert, dass Verweise ins Leere zeigen.</p></div><p>Bei vielen Verweisen hilft eine gefilterte Ansicht im verweisenden Grid, um alle betroffenen Einträge zu finden.</p><h2 id="filtern-nach-verknupfungen" tabindex="-1">Filtern nach Verknüpfungen <a class="header-anchor" href="#filtern-nach-verknupfungen" aria-label="Permalink to &quot;Filtern nach Verknüpfungen&quot;">​</a></h2><p>Verknüpfungsfelder unterstützen die Bedingungen <em>ist leer</em> und <em>ist nicht leer</em>. Bei <strong>Mehrere Einträge verknüpfen</strong> kommen <em>enthält eines von</em>, <em>enthält keines von</em> und <em>enthält alle von</em> hinzu.</p><div class="tip custom-block"><p class="custom-block-title">Unvollständige Datensätze finden</p><p>Ein Filter <code>Veranstaltung</code> <code>ist leer</code> zeigt alle Anmeldungen ohne zugeordnete Veranstaltung — der schnellste Weg zu Datenlücken nach einem Import.</p></div><h2 id="was-danach-moglich-wird" tabindex="-1">Was danach möglich wird <a class="header-anchor" href="#was-danach-moglich-wird" aria-label="Permalink to &quot;Was danach möglich wird&quot;">​</a></h2><p>Erst mit einer Verknüpfung funktionieren die berechneten Feldtypen:</p><ul><li><strong>Wert übernehmen</strong> — holt einen Wert aus dem verknüpften Eintrag, etwa das Veranstaltungsdatum in die Anmeldung</li><li><strong>Summe berechnen</strong> — summiert über mehrere verknüpfte Einträge, etwa die Positionen einer Rechnung</li></ul><p>→ <a href="/docs/grids/berechnete-felder">Berechnete Felder</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/grids/berechnete-felder">Berechnete Felder</a></li><li><a href="/docs/referenz/spaltentypen">Spaltentypen-Referenz</a></li><li><a href="/docs/grids/felder">Felder anlegen und ändern</a></li></ul>`,36)])])}const p=n(a,[["render",s]]);export{c as __pageData,p as default};
